def recall_at_k(casos, buscar, k=5):
    acertos = 0
    for caso in casos:
        fontes = {r.fonte for r in buscar(caso["pergunta"], k)}
        acertos += caso["fonte_esperada"] in fontes
    return acertos / len(casos)

